package co.com.bancolombia.factory.upgrades.actions;

import co.com.bancolombia.factory.ModuleBuilder;
import co.com.bancolombia.factory.upgrades.UpgradeAction;
import co.com.bancolombia.utils.FileUtils;
import java.io.File;
import java.io.IOException;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Replaces the AWS credentials providers generated by the scaffold (the SQS provider chain and the
 * web identity provider of DynamoDB and S3) with the SDK default credentials provider chain. Only
 * the code generated by the scaffold is changed: a customized chain is kept as is.
 */
public class UpgradeY2026M11D07AwsDefaultCredentialsProvider implements UpgradeAction {
  private static final String DEFAULT_PROVIDER = "DefaultCredentialsProvider";
  private static final String USE_DEFAULT_PROVIDER =
      ".credentialsProvider(" + DEFAULT_PROVIDER + ".builder().build())";
  private static final String USE_PROVIDER_CHAIN = ".credentialsProvider(getProviderChain())";
  private static final String USE_WEB_IDENTITY_PROVIDER =
      ".credentialsProvider(WebIdentityTokenFileCredentialsProvider.create())";
  private static final Pattern SCAFFOLD_PROVIDER_CHAIN =
      Pattern.compile(
          "\\n[ \\t]*private AwsCredentialsProviderChain getProviderChain\\(\\) \\{\\s*"
              + "return AwsCredentialsProviderChain\\.builder\\(\\)\\s*"
              + "\\.addCredentialsProvider\\(EnvironmentVariableCredentialsProvider\\.create\\(\\)\\)\\s*"
              + "\\.addCredentialsProvider\\(SystemPropertyCredentialsProvider\\.create\\(\\)\\)\\s*"
              + "\\.addCredentialsProvider\\(WebIdentityTokenFileCredentialsProvider\\.create\\(\\)\\)\\s*"
              + "\\.addCredentialsProvider\\(ProfileCredentialsProvider\\.create\\(\\)\\)\\s*"
              + "\\.addCredentialsProvider\\(ContainerCredentialsProvider\\.builder\\(\\)\\.build\\(\\)\\)\\s*"
              + "\\.addCredentialsProvider\\(InstanceProfileCredentialsProvider\\.create\\(\\)\\)\\s*"
              + "\\.build\\(\\);\\s*}\\n");
  private static final Pattern CREDENTIALS_IMPORT =
      Pattern.compile("(?m)^import software\\.amazon\\.awssdk\\.auth\\.credentials\\.(\\w+);\\n");

  @Override
  public boolean up(ModuleBuilder builder) {
    AtomicBoolean applied = new AtomicBoolean(false);
    FileUtils.allFiles(
        builder.getProjectDir(),
        file -> apply(builder, file, applied),
        (dir, name) -> name.endsWith(".java") && !isBuildOutput(dir));
    return applied.get();
  }

  private static boolean isBuildOutput(File dir) {
    String path = dir.getAbsolutePath().replace('\\', '/') + "/";
    return path.contains("/build/") || path.contains("/.gradle/");
  }

  private void apply(ModuleBuilder builder, File file, AtomicBoolean applied) {
    try {
      if (builder.updateFile(file.getAbsolutePath(), this::upgrade)) {
        builder.getLogger().lifecycle("AWS default credentials provider applied in {}", file);
        applied.set(true);
      }
    } catch (IOException e) {
      builder.getLogger().warn("Error updating the AWS credentials provider of {}", file, e);
    }
  }

  String upgrade(String content) {
    String result = content;
    if (result.contains(USE_PROVIDER_CHAIN)) {
      Matcher chain = SCAFFOLD_PROVIDER_CHAIN.matcher(result);
      if (!chain.find()) {
        return content; // customized chain
      }
      result = chain.replaceFirst("").replace(USE_PROVIDER_CHAIN, USE_DEFAULT_PROVIDER);
      if (result.contains("getProviderChain(")) {
        return content; // the chain is used somewhere else
      }
    }
    result = result.replace(USE_WEB_IDENTITY_PROVIDER, USE_DEFAULT_PROVIDER);
    if (result.equals(content)) {
      return content;
    }
    return updateCredentialsImports(content, result);
  }

  /** Keeps the credentials imports still in use, plus the default provider, sorted. */
  private static String updateCredentialsImports(String original, String upgraded) {
    Matcher imports = CREDENTIALS_IMPORT.matcher(upgraded);
    if (!imports.find()) {
      return original; // wildcard or unexpected imports
    }
    int position = imports.start();
    Set<String> classes = new TreeSet<>();
    classes.add(DEFAULT_PROVIDER);
    imports.reset();
    while (imports.find()) {
      classes.add(imports.group(1));
    }
    String code = CREDENTIALS_IMPORT.matcher(upgraded).replaceAll("");
    StringBuilder block = new StringBuilder();
    for (String clazz : classes) {
      if (Pattern.compile("\\b" + clazz + "\\b").matcher(code).find()) {
        block.append("import software.amazon.awssdk.auth.credentials.").append(clazz).append(";\n");
      }
    }
    return code.substring(0, position) + block + code.substring(position);
  }

  @Override
  public String name() {
    return "AWS default credentials provider";
  }

  @Override
  public String description() {
    return "Use the AWS SDK default credentials provider in the SQS, S3 and DynamoDB configurations";
  }
}
